INSERT INTO `configurations` (`configuration_id`,`bundle_id`,`config_type`,`config_key`,`description`,`config_value`,`target`,`isPreLoginConfiguration`) VALUES ('SME_91','NUO_CONFIG_SME_BUNDLE','PREFERENCE','USER_ACTION_FINANCIALSTATEMENTS_CONFIG','financialStatements','{\"UserActionName\":\"FinancialStatements\",\"Group\":\"Documents\",\"Skippable\":\"false\",\"ActionLevel\":\"Applicant\",\"Title\":\"Financials for the last 3 years %FirstName% %LastName%\",\"Title_Key\":\"FinancialStatement_Title\",\"InformationText\":\"<h4>The file(s) must follow with the below rules:</h4>Cannot contain the following special characters: , * | : \\\" < > ? / \\\\ [ ] % = ;<br>File name must have an extension name (eg: .pdf, .jpg, .png)<br>File name can’t begin with space<br>File can’t exclude more than 2MB\",\"InformationText_Key\":\"FinancialStatement_InformationText\",\"UserActionType\":\"DocumentUpload\",\"Options\":\"\",\"OptionsType\":\"\",\"Description\":\"The user should upload single or multiple document(s), as applicable.\",\"Description_Key\":\"FinancialStatement_Description\",\"DynamicDataDefinition\":{\"PersonalInfo\":[{\"name\":\"FirstName\",\"path\":\"$.FirstName\"},{\"name\":\"LastName\",\"path\":\"$.LastName\"}]},\"NeedsReview\":\"false\",\"isPreRequirement\":\"true\"}','CLIENT','1');
