INSERT INTO `configurations` (`configuration_id`,`bundle_id`,`config_type`,`config_key`,`description`,`config_value`,`target`,`isPreLoginConfiguration`) VALUES ('SME_103','NUO_CONFIG_SME_BUNDLE','PREFERENCE','USER_ACTION_LOANFINANCIALSTATEMENTS_CONFIG','loanFinancialStatements','{\"UserActionName\":\"LoanFinancialStatements\",\"Group\":\"Documents\",\"Skippable\":\"false\",\"ActionLevel\":\"Application\",\"Title\":\"Financials for the last 3 years %FirstName% %LastName%\",\"Title_Key\":\"LoanFinancialStatements_Title\",\"InformationText\":\"<h4>The file(s) must follow with the below rules:</h4>Cannot contain the following special characters: , * | : \\\" < > ? / \\\\ [ ] % = ;<br>File name must have an extension name (eg: .pdf, .jpg, .png)<br>File name can’t begin with space<br>File can’t exclude more than 2MB\",\"InformationText_Key\":\"LoanFinancialStatements_InformationText\",\"UserActionType\":\"DocumentUpload\",\"Options\":\"\",\"OptionsType\":\"\",\"Description\":\"The user should upload single or multiple document(s), as applicable.\",\"Description_Key\":\"LoanFinancialStatements_Description\",\"DynamicDataDefinition\":{\"PersonalInfo\":[{\"name\":\"FirstName\",\"path\":\"$.FirstName\"},{\"name\":\"LastName\",\"path\":\"$.LastName\"}]},\"NeedsReview\":\"false\",\"isPreRequirement\":\"true\"}','CLIENT','1');
